namespace NShape {

struct CSubdivisionTriangle {
    virtual void v00();
    virtual void v01();
    virtual void v02();
    virtual void v03();
    virtual unsigned char IsPosInShape(const C3DVector& pos);   // slot 4
};

template <class T>
